import dictionary from './translations.js';
export const languages=['ca','es','en'];
let language='ca';try{const saved=globalThis.document&&globalThis.localStorage?.getItem('bord-language');if(languages.includes(saved))language=saved;else{const requested=new URLSearchParams(globalThis.location?.search||'').get('lang');if(languages.includes(requested))language=requested}}catch{}
const escape=s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
const keys=Object.keys(dictionary).filter(k=>dictionary[k].es!==k||dictionary[k].en!==k).sort((a,b)=>b.length-a.length);
const pattern=new RegExp(keys.map(escape).join('|'),'gu');
export const getLanguage=()=>language;
export function translate(text,lang=language){if(lang==='ca')return String(text);return String(text).replace(pattern,key=>dictionary[key]?.[lang]??key)}
const originalText=new WeakMap(),originalAttributes=new WeakMap();
function ignored(node,attributes=false){for(let el=node.nodeType===3?node.parentElement:node;el;el=el.parentElement)if((['SCRIPT','STYLE'].includes(el.tagName)||!attributes&&['TEXTAREA','INPUT'].includes(el.tagName))||el.hasAttribute?.('data-user-text'))return true;return false}
export function translateDOM(root=globalThis.document){const doc=globalThis.document;if(!doc?.createTreeWalker||!root)return;const walker=doc.createTreeWalker(root,4);let node;while((node=walker.nextNode())){if(ignored(node)||!node.nodeValue.trim())continue;const value=node.nodeValue,old=originalText.get(node),source=old&&old.translated===value?old.source:value,translated=translate(source);originalText.set(node,{source,translated});if(value!==translated)node.nodeValue=translated}
 for(const el of root.querySelectorAll?.('[aria-label],[placeholder],[title],[alt],meta[name="description"]')||[]){if(ignored(el,true))continue;const entries=originalAttributes.get(el)||{};for(const attr of ['aria-label','placeholder','title','content','alt']){if(!el.hasAttribute(attr))continue;const value=el.getAttribute(attr),old=entries[attr],source=old&&old.translated===value?old.source:value,translated=translate(source);entries[attr]={source,translated};if(value!==translated)el.setAttribute(attr,translated)}originalAttributes.set(el,entries)}}
let onChange=()=>{};
export function setLanguage(lang){if(!languages.includes(lang))return;language=lang;try{globalThis.localStorage?.setItem('bord-language',lang)}catch{}const doc=globalThis.document;if(doc?.documentElement)doc.documentElement.lang=lang;const manifest=doc?.querySelector?.('link[rel=manifest]');if(manifest)manifest.setAttribute('href',lang==='ca'?'./manifest.webmanifest':'./manifest.'+lang+'.webmanifest');const picker=doc?.querySelector?.('#language');if(picker)picker.value=lang;onChange();translateDOM()}
export function initLanguages(callback){onChange=callback||(()=>{});const picker=globalThis.document?.querySelector?.('#language');if(picker)picker.onchange=()=>setLanguage(picker.value);setLanguage(language);if(typeof MutationObserver!=='undefined'){let queued=false;new MutationObserver(()=>{if(queued)return;queued=true;queueMicrotask(()=>{queued=false;translateDOM()})}).observe(document.documentElement,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['aria-label','placeholder','title','content','alt']})}}
